for name,before,after,edits in payload['changes']:
    path=Path(name); data=path.read_bytes()
    assert hashlib.sha256(data).hexdigest()==before,(name,'source changed since inspection')
    lines=data.decode().splitlines(keepends=True)
    for start,end,text in reversed(edits):lines[start:end]=[text]
    result=''.join(lines).encode()
    assert hashlib.sha256(result).hexdigest()==after,(name,'patch mismatch')
    path.write_bytes(result)
out=Path(os.environ['HIGHLIGHT_RECEIPTS']);out.mkdir(parents=True,exist_ok=True)
for name,text in payload['helpers'].items():(out/name).write_text(text)
(out/'source-hashes.json').write_text(json.dumps({name:after for name,before,after,edits in payload['changes']},indent=2))
